#include <iostream>
#include <memory>
#include <utility>

// Minimal singly linked list implementation
template <typename T>
class List {
private:
    struct Node {
        T data;
        std::unique_ptr<Node> next;
        explicit Node(const T& val) : data(val), next(nullptr) {}
    };
    std::unique_ptr<Node> firstPtr{nullptr};

public:
    List() = default;
    ~List() = default;

    bool isEmpty() const {
        return firstPtr == nullptr;
    }

    void insertAtFront(const T& value) {
        auto newNode = std::make_unique<Node>(value);
        newNode->next = std::move(firstPtr);
        firstPtr = std::move(newNode);
    }

    bool removeFromFront(T& value) {
        if (isEmpty()) return false;
        value = firstPtr->data;
        firstPtr = std::move(firstPtr->next);
        return true;
    }

    void print() const {
        if (isEmpty()) {
            std::cout << "The list is empty\n\n";
            return;
        }
        std::cout << "The list is: ";
        const Node* current = firstPtr.get();
        while (current != nullptr) {
            std::cout << current->data << " ";
            current = current->next.get();
        }
        std::cout << "\n\n";
    }
};

// Stack implemented via Composition
template <typename STACKTYPE>
class Stack {
public:
    void push(const STACKTYPE& data) {
        stackList.insertAtFront(data);
    }

    bool pop(STACKTYPE& data) {
        return stackList.removeFromFront(data);
    }

    bool isStackEmpty() const {
        return stackList.isEmpty();
    }

    void printStack() const {
        stackList.print();
    }

private:
    List<STACKTYPE> stackList; // Composed List object
};

int main() {
    Stack<int> intStack;
    std::cout << "processing an integer Stack\n";
    for (int i = 0; i < 3; ++i) {
        intStack.push(i);
        intStack.printStack();
    }

    int popInteger;
    while (!intStack.isStackEmpty()) {
        intStack.pop(popInteger);
        std::cout << popInteger << " popped from stack\n";
        intStack.printStack();
    }
    return 0;
}

