#include <iostream>

// Singly linked list with head and tail pointers for O(1) front/back ops
template <typename T>
class List {
private:
    struct Node {
        T data;
        Node* next{nullptr};
        explicit Node(const T& val) : data(val) {}
    };
    Node* firstPtr{nullptr};
    Node* lastPtr{nullptr};

public:
    List() = default;
    ~List() {
        while (!isEmpty()) {
            T temp;
            removeFromFront(temp);
        }
    }

    bool isEmpty() const {
        return firstPtr == nullptr;
    }

    void insertAtBack(const T& value) {
        Node* newNode = new Node(value);
        if (isEmpty()) {
            firstPtr = lastPtr = newNode;
        } else {
            lastPtr->next = newNode;
            lastPtr = newNode;
        }
    }

    bool removeFromFront(T& value) {
        if (isEmpty()) return false;
        Node* temp = firstPtr;
        value = temp->data;
        if (firstPtr == lastPtr) {
            firstPtr = lastPtr = nullptr;
        } else {
            firstPtr = firstPtr->next;
        }
        delete temp;
        return true;
    }

    void print() const {
        if (isEmpty()) {
            std::cout << "The list is empty\n\n";
            return;
        }
        std::cout << "The list is: ";
        Node* current = firstPtr;
        while (current != nullptr) {
            std::cout << current->data << " ";
            current = current->next;
        }
        std::cout << "\n\n";
    }
};

// Queue class template via private inheritance
template <typename QUEUETYPE>
class Queue : private List<QUEUETYPE> {
public:
    void enqueue(const QUEUETYPE& data) {
        this->insertAtBack(data);
    }

    bool dequeue(QUEUETYPE& data) {
        return this->removeFromFront(data);
    }

    bool isQueueEmpty() const {
        return this->isEmpty(); // 'this->' required for dependent name lookup
    }

    void printQueue() const {
        this->print(); // 'this->' required for dependent name lookup
    }
};

int main() {
    Queue<int> intQueue;
    std::cout << "processing an integer Queue\n";
    for (int i = 0; i < 3; ++i) {
        intQueue.enqueue(i);
        intQueue.printQueue();
    }

    int dequeueInteger;
    while (!intQueue.isQueueEmpty()) {
        intQueue.dequeue(dequeueInteger);
        std::cout << dequeueInteger << " dequeued\n";
        intQueue.printQueue();
    }
    return 0;
}
